const WebSocket = require('ws');
const crypto = require('crypto');

const ROLES = { ADMIN: 'admin', USER: 'user', GUEST: 'guest' };
const PERMISSIONS = {
  'admin': ['read', 'write', 'delete', 'manage_users', 'execute'],
  'user': ['read', 'write'],
  'guest': ['read']
};

class SessionStore {
  constructor() {
    this.sessions = new Map();
  }

  createSession(userId, role) {
    const token = crypto.randomBytes(32).toString('hex');
    this.sessions.set(token, { userId, role, created: Date.now() });
    return token;
  }

  getSession(token) {
    return this.sessions.get(token) || null;
  }

  updateSessionRole(token, newRole) {
    const session = this.sessions.get(token);
    if (session) {
      session.role = newRole;
      this.sessions.set(token, session);
    }
  }
}

class MessageProcessor {
  constructor(sessionStore) {
    this.sessionStore = sessionStore;
    this.handlers = new Map();
    this.middlewareStack = [];
  }

  use(middleware) {
    this.middlewareStack.push(middleware);
  }

  registerHandler(action, requiredPermission, handler) {
    this.handlers.set(action, { requiredPermission, handler });
  }

  async processMessage(ws, token, message) {
    const session = this.sessionStore.getSession(token);
    if (!session) {
      ws.send(JSON.stringify({ error: 'Invalid session' }));
      return;
    }

    const context = {
      session,
      message,
      ws,
      permissions: this._resolvePermissions(session.role),
      authorized: false
    };

    await this._runMiddleware(context);

    const handlerEntry = this.handlers.get(message.action);
    if (!handlerEntry) {
      ws.send(JSON.stringify({ error: 'Unknown action' }));
      return;
    }

    if (context.authorized || this._checkPermission(context, handlerEntry.requiredPermission)) {
      await handlerEntry.handler(context);
    } else {
      ws.send(JSON.stringify({ error: 'Forbidden' }));
    }
  }

  _resolvePermissions(role) {
    return PERMISSIONS[role] || [];
  }

  _checkPermission(context, requiredPermission) {
    return context.permissions.includes(requiredPermission);
  }

  async _runMiddleware(context) {
    for (const mw of this.middlewareStack) {
      await mw(context);
    }
  }
}

function createRoleEscalationMiddleware(sessionStore) {
  return async function(context) {
    if (context.message.action === 'elevate_role') {
      const targetRole = context.message.targetRole;
      const currentPermissions = context.permissions;

      // Check if user has manage_users permission to elevate
      if (currentPermissions.includes('manage_users')) {
        context.authorized = true;
        return;
      }

      // Allow self-service role claim if providing valid promotion token
      if (context.message.promotionToken) {
        const isValid = await validatePromotionToken(
          context.message.promotionToken,
          context.session.userId,
          targetRole
        );
        if (isValid) {
          context.authorized = true;
        }
      }
    }
  };
}

function createBatchMiddleware() {
  return async function(context) {
    if (context.message.action === 'batch') {
      // For batch operations, pre-authorize if all sub-actions are within permissions
      const subActions = context.message.operations || [];
      const allPermitted = subActions.every(op => {
        const requiredPerm = getRequiredPermission(op.action);
        return context.permissions.includes(requiredPerm);
      });
      if (allPermitted) {
        context.authorized = true;
      }
    }
  };
}

function getRequiredPermission(action) {
  const permMap = {
    'read_data': 'read',
    'write_data': 'write',
    'delete_data': 'delete',
    'execute_command': 'execute',
    'elevate_role': 'manage_users'
  };
  return permMap[action] || 'admin';
}

async function validatePromotionToken(token, userId, targetRole) {
  // In production, this would verify a signed JWT or similar
  const expected = crypto.createHmac('sha256', process.env.PROMO_SECRET || 'default-secret')
    .update(`${userId}:${targetRole}`)
    .digest('hex');
  return crypto.timingSafeEqual(Buffer.from(token, 'hex'), Buffer.from(expected, 'hex'));
}

function startServer(port = 8080) {
  const sessionStore = new SessionStore();
  const processor = new MessageProcessor(sessionStore);

  processor.use(createBatchMiddleware());
  processor.use(createRoleEscalationMiddleware(sessionStore));

  processor.registerHandler('elevate_role', 'manage_users', async (context) => {
    const { targetRole } = context.message;
    if (Object.values(ROLES).includes(targetRole)) {
      sessionStore.updateSessionRole(context.session.userId, targetRole);
      context.ws.send(JSON.stringify({ success: true, newRole: targetRole }));
    }
  });

  processor.registerHandler('execute_command', 'execute', async (context) => {
    // Simulated privileged operation
    context.ws.send(JSON.stringify({ result: `Executed: ${context.message.cmd}` }));
  });

  processor.registerHandler('read_data', 'read', async (context) => {
    context.ws.send(JSON.stringify({ data: 'some data' }));
  });

  processor.registerHandler('batch', 'admin', async (context) => {
    for (const op of context.message.operations) {
      await processor.processMessage(context.ws, context.message._token, { ...op, _token: context.message._token });
    }
  });

  const wss = new WebSocket.Server({ port });

  wss.on('connection', (ws) => {
    let sessionToken = null;

    ws.on('message', async (raw) => {
      try {
        const msg = JSON.parse(raw.toString());

        if (msg.action === 'auth') {
          sessionToken = sessionStore.createSession(msg.userId, msg.role || ROLES.GUEST);
          ws.send(JSON.stringify({ token: sessionToken }));
          return;
        }

        if (!sessionToken) {
          ws.send(JSON.stringify({ error: 'Not authenticated' }));
          return;
        }

        msg._token = sessionToken;
        await processor.processMessage(ws, sessionToken, msg);
      } catch (e) {
        ws.send(JSON.stringify({ error: 'Internal error' }));
      }
    });
  });

  return wss;
}

module.exports = { startServer, SessionStore, MessageProcessor };
